    url: 'https://scryfall.com/card/znr/122/scourge-of-the-skyclaves',
    image: 'https://cards.scryfall.io/normal/front/4/d/4dea7bcc-3ff8-40b0-8264-0cd678d6ff31.jpg?1783929370',
