    rarity: 'rare',
    typeLine: 'Sorcery',
    url: 'https://scryfall.com/card/znr/124/shadows-verdict',
    image: 'https://cards.scryfall.io/normal/front/5/2/52470883-b44d-415b-9324-8074e66f79ae.jpg?1783929366',
    artist: 'Lius Lasahido',
    subject: '\'죽음의 그림자는 결국 모두에게 드리워진다.\' — 망토를 펼친 거대한 두건 그림자가 작은 사람 셋을 덮어 어둠에 잠기게 하는 모습(앞면 집중마법, 장면). 작은 상징 — 카비라 지역 상세 대상.',
    depicts: { type: 'location', id: 'agadeem' },
    at: [407, 1597.5],
