    set: 'znr',
    number: '209',
    rarity: 'rare',
    typeLine: 'Creature — Elf',
    url: 'https://scryfall.com/card/znr/209/tajuru-paragon',
    image: 'https://cards.scryfall.io/normal/front/a/0/a045dd0f-953a-4022-8f29-0758f2b6ccaa.jpg?1783929330',
