    sources: [{ label: 'Card: Vastwood Surge (ZNR #217) 한국어판 \'광활림의 급등\' — 플레이버 없음', url: 'https://scryfall.com/card/znr/217/ko' }, { label: 'Card: Oran-Rief, the Vastwood (ZEN #221)', url: 'https://scryfall.com/card/zen/221/oran-rief-the-vastwood' }, { label: 'The Art of Magic: The Gathering – Zendikar (James Wyatt, 2016) — \'Oran-Rief, the Vastwood\': \'contributing to the forest\'s nickname, the Vastwood\'', url: 'https://archive.org/details/artofmagicthegat0000wyat' }, { label: 'Plane Shift: Zendikar (2016) — \'the Vastwood of Tazeem\'', url: 'https://media.wizards.com/2016/downloads/magic/Plane%20Shift%20Zendikar.pdf' }],
